fn at(xs: List[Int], i: Int) -> Int {
    match xs.get(i) {
        Some(v) => {
            return v
        }
        None => {
            return 0
        }
    }
}

pub fn lis(xs: List[Int]) -> List[Int] {
    let n = xs.len()

    // rev[k] holds the length of the longest increasing run starting at index n - 1 - k
    var rev: List[Int] = []
    var i = n - 1
    while i >= 0 {
        var best = 1
        var j = i + 1
        while j < n {
            if at(xs, j) > at(xs, i) {
                let c = at(rev, n - 1 - j) + 1
                if c > best {
                    best = c
                }
            }
            j = j + 1
        }
        rev = rev.push(best)
        i = i - 1
    }

    var best_len = 0
    for v in rev {
        if v > best_len {
            best_len = v
        }
    }

    var out: List[Int] = []
    var remaining = best_len
    var pos = 0
    var has_prev = false
    var prev = 0
    while remaining > 0 {
        var found = false
        var bestv = 0
        var bestj = 0
        var j = pos
        while j < n {
            let lj = at(rev, n - 1 - j)
            let v = at(xs, j)
            if lj >= remaining and (not has_prev or v > prev) {
                if not found or v < bestv {
                    found = true
                    bestv = v
                    bestj = j
                }
            }
            j = j + 1
        }
        if not found {
            break
        }
        out = out.push(bestv)
        prev = bestv
        has_prev = true
        pos = bestj + 1
        remaining = remaining - 1
    }
    return out
}
